import { Router } from "express";
import { buildCreateUserHandler } from "../controllers/user.controller.js";
import { validateResource } from "../middlewares/validate.js";
import { createUserSchema } from "../schemas/user.schema.js";
import type { PrismaClient } from "@prisma/client";
import { database } from "@eventflow/database";

export function createUserRouter(prisma: PrismaClient = database): Router {
  const router = Router();

  router.post(
    "/api/users",
    validateResource(createUserSchema),
    buildCreateUserHandler(prisma),
  );

  return router;
}

export const userRouter = createUserRouter();
